    # Check for tool calls that contain submit actions
    if 'toolCall' in msg and msg['toolCall'].get('name') == 'ipython':
        code = msg['toolCall'].get('arguments', {}).get('code', '')
        if 'submit' in code.lower() or 'correct' in code.lower() or 'incorrect' in code.lower():
            submitted_solutions.append({
                'line': i,
