            if 'correct' in message_text.lower() or 'incorrect' in message_text.lower():
                feedback_found = True
                print(f"\n=== FEEDBACK FOUND at line {i} ===")
                print(line)

print(f"\nTotal tool calls with submit/decorate keywords: {len(submitted_solutions)}")
