import json

with open(full_path, 'r') as f:
    lines = f.readlines()

# Count actions per type after the initial submission
actions_by_type = {
    'submit': [],
    'request_demos': [],
    'finish': []
}

for i, line in enumerate(lines):
    line_dict = json.loads(line)
    if line_dict.get('type') == 'message' and line_dict.get('role') == 'assistant':
        # Check for tool call
        if 'toolCall' in line_dict:
            action_type = None
            tool_id = line_dict['toolCall'].get('id', '')
            if 'submit' in line_dict.get('toolCall', {}).get('arguments', {}).get('code', '').lower():
                action_type = 'submit'
            elif 'demos' in line_dict.get('toolCall', {}).get('arguments', {}).get('code', '').lower() and 'request' in line_dict.get('toolCall', {}).get('arguments', {}).get('code', '').lower():
                action_type = 'request_demos'
            elif 'finish' in line_dict.get('toolCall', {}).get('arguments', {}).get('code', '').lower():
                action_type = 'finish'

            if action_type:
                actions_by_type[action_type].append((i, line_dict['toolCall'].get('id'), line_dict.get('timestamp', '')))

# Show submissions and any demos requested
print("=== SUBMISSIONS ===")
for line_n, tool_id, ts in actions_by_type['submit']:
    print(f"Line {line_n} ({ts}): Tool {tool_id[:8]}")

print(f"\n=== DEMO REQUESTS ===")
for line_n, tool_id, ts in actions_by_type['request_demos']:
    print(f"Line {line_n} ({ts}): Tool {tool_id[:8]}")

print(f"\n=== FINISH ===")
for line_n, tool_id, ts in actions_by_type['finish']:
    print(f"Line {line_n} ({ts}): Tool {tool_id[:8]}")

print(f"\n=== SUMMARY ===")
print(f"Submissions: {len(actions_by_type['submit'])}")
print(f"Demos requested: {len(actions_by_type['request_demos'])}")
print(f"Finish called: {len(actions_by_type['finish'])}")

# Now look for the LAST message (the one to respond to)
if lines:
    last_line = json.loads(lines[-1])
    print(f"\n=== LAST MESSAGE in log ===")
    print(last_line)

